head.script:
scwin.screenId = "jldods70001_create";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goWrite((dma_report.get("formCd") ?? (() => { throw new Error("unresolved:" + "dma_report.formCd"); })()), (dma_report.get("formVer") ?? (() => { throw new Error("unresolved:" + "dma_report.formVer"); })()), '' + dma_report.get("formAdmInstTpCd") + '', '' + dma_report.get("inqdisclsTpCd") + '', '0', (dma_report.get("formUpclssCd") ?? (() => { throw new Error("unresolved:" + "dma_report.formUpclssCd"); })()), (dma_report.get("rsnClssCd") ?? (() => { throw new Error("unresolved:" + "dma_report.rsnClssCd"); })()), '' + dma_report.get("applFormYn") + '', (dma_report.get("ldMktTpCd") ?? (() => { throw new Error("unresolved:" + "dma_report.ldMktTpCd"); })()), '' + dma_report.get("formWrtMethdTpCd") + '', '' + dma_report.get("byformUsrTpCd") + '', (dma_report.get("exmptObjDisclsYn") ?? (() => { throw new Error("unresolved:" + "dma_report.exmptObjDisclsYn"); })()), '' + dma_report.get("ismulti") + '', '' + dma_report.get("editClssCd") + '', '' + dma_report.get("disclsWrtObjYn") + '');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70001_create.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70001_create.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.form_69_onsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.form_69_onsubmit = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin form_69_onsubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70001_create.form_69_onsubmit' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_registerDisclosureAction
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_registerDisclosureAction = async function () {
    const sbmOptions = {
        id: "tx_registerDisclosureAction",
        method: "post",
        action: "/discls/disclosurereg.do?method=registerDisclosure",
        ref: "dma_registerDisclosureActionReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods70001_create.tx_registerDisclosureAction" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

